// Matmul throughput / energy benchmark for the ET-SoC-1 tensor unit.
//
// Hart 0 of every minion in the launch runs back-to-back 16x16xK TensorFMA ops,
// with the same inner loop as gp-sdk's autogenerated matmul (libautogen): A is
// tensor_load-ed into one of two L1 scratchpad buffers (lines 0-15 / 16-31), B is
// streamed through TenB by a paired tensor_load, and C accumulates in f0..f31.
// The next op's loads are issued while the current FMA runs.  A small tile pool
// stays in the shire L2, which makes the loop compute bound. A large private
// pool per minion makes every load come from DRAM.
//
// Result per minion: C = iters * sum_t A_t * B_t over its tiles, checked by the host.
#include <etsoc/common/utils.h>
#include <etsoc/isa/hart.h>
#include <etsoc/isa/tensors.h>

#include "entryPoint.h"
#include "mmbench_args.h"

int mmbench(MmBenchArgs* args);
// Tensor ops may only be issued from hart 0, so hart 1 of each minion stays idle.
DECLARE_KERNEL_ENTRY_POINTS(mmbench, nullptr);

namespace {

// TensorFMA control word (field layout as decoded in sw-sysemu insns/tensors.cpp):
// 16 A rows x 16 32-bit A words (K = 16 fp32 / 32 fp16 / 64 int8) x 16 B columns.
inline uint64_t fmaControl(uint32_t type, uint64_t aLine, bool firstPass, bool tencToRf) {
  return (3ull << 55)                   // B columns: (3 + 1) * 4 = 16
         | (15ull << 51)                // A rows: 16
         | (15ull << 47)                // A columns: 16 words
         | (uint64_t(tencToRf) << 23)   // int8: copy the TenC accumulator into f0..f31
         | (1ull << 20)                 // B is the paired TenB load
         | (aLine << 4)                 // first L1 scratchpad line of A
         | (uint64_t(type & 7) << 1)    // fp32 / fp16->fp32 / int8->int32
         | uint64_t(firstPass);         // 1: C = A*B, 0: C += A*B
}

inline void tensorFma(uint64_t control) {
  __asm__ __volatile__("csrw 0x801, %0" : : "r"(control) : "memory");
}

// Stores the 16x16 32-bit accumulator (row i lives in f[2i], f[2i+1]) to c[0..255].
// Each minion writes its own 16 lines, so plain L1 stores are safe.
inline void storeAccumulator(uint64_t c) {
  __asm__ __volatile__(
    "fmv.x.w x0, f0\n"          // errata 1.29 type F: let the TensorFMA's last VPURF write land
    "mov.m.x m0, zero, 0xff\n"  // store all 8 lanes
    "fsw.ps f0, 0(%0)\n    fsw.ps f1, 32(%0)\n   fsw.ps f2, 64(%0)\n   fsw.ps f3, 96(%0)\n"
    "fsw.ps f4, 128(%0)\n  fsw.ps f5, 160(%0)\n  fsw.ps f6, 192(%0)\n  fsw.ps f7, 224(%0)\n"
    "fsw.ps f8, 256(%0)\n  fsw.ps f9, 288(%0)\n  fsw.ps f10, 320(%0)\n fsw.ps f11, 352(%0)\n"
    "fsw.ps f12, 384(%0)\n fsw.ps f13, 416(%0)\n fsw.ps f14, 448(%0)\n fsw.ps f15, 480(%0)\n"
    "fsw.ps f16, 512(%0)\n fsw.ps f17, 544(%0)\n fsw.ps f18, 576(%0)\n fsw.ps f19, 608(%0)\n"
    "fsw.ps f20, 640(%0)\n fsw.ps f21, 672(%0)\n fsw.ps f22, 704(%0)\n fsw.ps f23, 736(%0)\n"
    "fsw.ps f24, 768(%0)\n fsw.ps f25, 800(%0)\n fsw.ps f26, 832(%0)\n fsw.ps f27, 864(%0)\n"
    "fsw.ps f28, 896(%0)\n fsw.ps f29, 928(%0)\n fsw.ps f30, 960(%0)\n fsw.ps f31, 992(%0)\n"
    :
    : "r"(c)
    : "memory");
}

} // namespace

int mmbench(MmBenchArgs* args) {
  const uint64_t hartId = get_hart_id();
  const uint64_t minion = hartId >> 1;  // shire * 32 + minion-in-shire
  if (minion >= args->num_minions || args->ntiles == 0 || args->iters == 0) {
    return 0;
  }
  const uint32_t type = args->mode;
  const uint64_t ntiles = args->ntiles;
  const uint64_t totalOps = args->iters * ntiles;
  const uint64_t poolOffset = args->private_pools ? minion * ntiles * MMBENCH_TILE_BYTES : 0;
  const uint64_t aTiles = args->a_tiles + poolOffset;
  const uint64_t bTiles = args->b_tiles + poolOffset;

  // With a shared pool, start each minion on a different tile to spread L2 traffic.
  uint64_t t = args->private_pools ? 0 : minion % ntiles;
  const uint64_t start = et_get_timestamp();
  for (uint64_t op = 0; op < totalOps; ++op) {
    const uint64_t aLine = (op & 1) * 16;  // double-buffer A in the L1 scratchpad
    const uint64_t offset = t * MMBENCH_TILE_BYTES;
    tensor_load(false, false, aLine, 0, 0, aTiles + offset, 0, 15, 64, 0);  // A -> L1Scp, id 0
    tensor_load(false, false, 0, 0, 1, bTiles + offset, 0, 15, 64, 1);      // B -> TenB, id 1
    tensor_wait(TENSOR_LOAD_WAIT_0);
    tensorFma(fmaControl(type, aLine, op == 0, type == MMBENCH_INT8 && op + 1 == totalOps));
    if (++t == ntiles) {
      t = 0;
    }
  }
  tensor_wait(TENSOR_FMA_WAIT);
  const uint64_t cycles = et_get_timestamp() - start;

  storeAccumulator(args->c_out + minion * MMBENCH_TILE_BYTES);
  auto* stats = reinterpret_cast<volatile MmBenchStats*>(args->stats_out) + minion;
  stats->cycles = cycles;
  stats->ops = totalOps;
  stats->hart_id = static_cast<uint32_t>(hartId);
  stats->magic = MMBENCH_MAGIC;
  return 0;
}
